import{useEffect,useState}from'react';import type{RouteConfig}from'@mercurjs/dashboard-sdk';declare const __BACKEND_URL__:string;export const config:RouteConfig={label:'المرتجعات',rank:68};const api=async(p:string,i?:RequestInit)=>{const r=await fetch(`${__BACKEND_URL__}${p}`,{credentials:'include',...i,headers:{...(i?.body?{'content-type':'application/json'}:{}),...(i?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||`HTTP ${r.status}`);return d};export default function P(){const[x,setX]=useState<any[]>([]),[m,setM]=useState('');const load=()=>api('/vendor/spike/returns').then(d=>setX(d.returns||[]));useEffect(()=>{load().catch(e=>setM(e.message))},[]);const act=async(id:string,a:string)=>{let reason='';if(a==='reject'&&!(reason=prompt('سبب الرفض')||''))return;await api(`/vendor/spike/returns/${id}`,{method:'POST',body:JSON.stringify({action:a,reason})});setM(a==='approve'?'تم قبول المرتجع وإضافة مبلغ العميل للمستحقات':'تم رفض المرتجع');load()};return <div dir="rtl" style={{padding:24}}><h1>المرتجعات</h1>{m&&<p>{m}</p>}<table style={{width:'100%'}}><thead><tr><th>الطلب</th><th>المنتج</th><th>المبلغ</th><th>الحالة</th><th></th></tr></thead><tbody>{x.map(r=><tr key={r.id}><td>{r.order_id}</td><td>{r.product_id}</td><td>{r.amount} {r.currency_code}</td><td>{r.status}</td><td>{r.status==='requested'&&<><button onClick={()=>act(r.id,'approve')}>قبول - رجع سليم</button> <button onClick={()=>act(r.id,'reject')}>رفض</button></>}</td></tr>)}</tbody></table></div>}
